<?php
require __DIR__.'/bootstrap.php';require_auth();if(!can('reports.view')){http_response_code(403);exit('Forbidden');}require __DIR__.'/partials.php';
$type=$_GET['type']??'invoice';$from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-d');$payment=$_GET['payment']??'';$channel=$_GET['channel']??'';$types=['invoice'=>'All Sales / Invoice-wise','product'=>'Item / Product-wise','category'=>'Category-wise','brand'=>'Brand-wise','customer'=>'Customer-wise','cashier'=>'Cashier-wise','method'=>'Payment Method-wise','credit'=>'Customer Credit & Outstanding','stock'=>'Current Stock & Value','purchase'=>'Purchases / Supplier-wise'];if(!isset($types[$type]))$type='invoice';$saleWhere='DATE(s.sale_date) BETWEEN ? AND ? AND s.status NOT IN("cancelled","returned")';$params=[$from,$to];if(in_array($payment,['cash','credit'],true)){$saleWhere.=' AND s.payment_type=?';$params[]=$payment;}if(in_array($channel,['retail','wholesale'],true)){$saleWhere.=' AND s.sale_type=?';$params[]=$channel;}$rows=[];
if($type==='invoice'){$sql='SELECT s.sale_no reference,COALESCE(c.name,"Walk-in") name,SUM(si.quantity) quantity,s.total sales,SUM(si.historical_unit_cost*si.quantity) cost,SUM(si.gross_profit) profit,s.status detail,s.id sale_id FROM sales s JOIN sale_items si ON si.sale_id=s.id LEFT JOIN customers c ON c.id=s.customer_id WHERE '.$saleWhere.' GROUP BY s.id ORDER BY s.sale_date DESC';}
elseif(in_array($type,['product','category','brand','customer','cashier'],true)){$map=['product'=>['p.item_code','p.name'],'category'=>['COALESCE(cat.name,"Uncategorised")','COALESCE(cat.name,"Uncategorised")'],'brand'=>['COALESCE(b.name,"No brand")','COALESCE(b.name,"No brand")'],'customer'=>['COALESCE(c.customer_code,"WALK-IN")','COALESCE(c.name,"Walk-in Customer")'],'cashier'=>['u.id','u.display_name']];[$ref,$name]=$map[$type];$sql="SELECT $ref reference,$name name,SUM(si.quantity) quantity,SUM(si.line_total) sales,SUM(si.historical_unit_cost*si.quantity) cost,SUM(si.gross_profit) profit,COUNT(DISTINCT s.id) detail,NULL sale_id FROM sales s JOIN sale_items si ON si.sale_id=s.id JOIN products p ON p.id=si.product_id LEFT JOIN categories cat ON cat.id=p.category_id LEFT JOIN brands b ON b.id=p.brand_id LEFT JOIN customers c ON c.id=s.customer_id JOIN users u ON u.id=s.created_by WHERE $saleWhere GROUP BY $ref,$name ORDER BY sales DESC";}
elseif($type==='method'){$sql='SELECT COALESCE(sp.method,"unpaid") reference,UPPER(REPLACE(COALESCE(sp.method,"unpaid"),"_"," ")) name,COUNT(DISTINCT s.id) quantity,COALESCE(SUM(sp.amount),0) sales,0 cost,0 profit,"payments" detail,NULL sale_id FROM sales s LEFT JOIN sale_payments sp ON sp.sale_id=s.id WHERE '.$saleWhere.' GROUP BY sp.method ORDER BY sales DESC';}
elseif($type==='credit'){$sql='SELECT s.sale_no reference,c.name name,1 quantity,s.total sales,SUM(si.historical_unit_cost*si.quantity) cost,SUM(si.gross_profit) profit,CONCAT("Outstanding: ",FORMAT(s.balance,2)," | Due: ",COALESCE(DATE_FORMAT(s.due_date,"%d %b %Y"),"not set")) detail,s.id sale_id FROM sales s JOIN customers c ON c.id=s.customer_id JOIN sale_items si ON si.sale_id=s.id WHERE '.$saleWhere.' AND s.payment_type="credit" GROUP BY s.id ORDER BY s.balance DESC';}
elseif($type==='stock'){$sql='SELECT p.item_code reference,p.name name,p.current_stock quantity,p.current_stock*p.retail_price sales,p.current_stock*p.avg_cost cost,p.current_stock*(p.retail_price-p.avg_cost) profit,IF(p.current_stock<=p.minimum_stock,"Low stock","Available") detail,NULL sale_id FROM products p WHERE p.status="active" ORDER BY p.current_stock*p.avg_cost DESC';$params=[];}
else{$sql='SELECT s.supplier_code reference,s.name name,SUM(pi.quantity) quantity,SUM(pi.line_total) sales,0 cost,0 profit,CONCAT(COUNT(DISTINCT p.id)," invoices | Owed: ",FORMAT(s.outstanding,2)) detail,NULL sale_id FROM purchases p JOIN suppliers s ON s.id=p.supplier_id JOIN purchase_items pi ON pi.purchase_id=p.id WHERE p.purchase_date BETWEEN ? AND ? AND p.status="posted" GROUP BY s.id ORDER BY sales DESC';$params=[$from,$to];}
$stmt=$db->prepare($sql);$stmt->execute($params);$rows=$stmt->fetchAll();$totalQty=array_sum(array_map(fn($r)=>(float)$r['quantity'],$rows));$totalSales=array_sum(array_map(fn($r)=>(float)$r['sales'],$rows));$totalCost=array_sum(array_map(fn($r)=>(float)$r['cost'],$rows));$totalProfit=array_sum(array_map(fn($r)=>(float)$r['profit'],$rows));
if(isset($_GET['export'])){$filename=preg_replace('/[^a-z0-9]+/i','-',strtolower($types[$type])).'-'.$from.'-'.$to.'.csv';header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="'.$filename.'"');$out=fopen('php://output','w');fputcsv($out,[$types[$type],$from.' to '.$to]);fputcsv($out,['Reference','Name','Quantity / Count','Sales / Value','Saved Cost','Gross Profit','Details']);foreach($rows as $r)fputcsv($out,[$r['reference'],$r['name'],$r['quantity'],$r['sales'],$r['cost'],$r['profit'],$r['detail']]);fputcsv($out,['TOTAL','',$totalQty,$totalSales,$totalCost,$totalProfit,'']);fclose($out);exit;}
page_start('Reports','reports.php');?>
<section class="report-head"><div><span class="eyebrow">Choose how to view the business</span><h2><?=e($types[$type])?></h2></div><div><a class="btn secondary" href="?<?=e(http_build_query(array_merge($_GET,['export'=>1])))?>">Download Excel/CSV</a> <button class="btn primary" onclick="window.print()">Print / Save PDF</button></div></section><section class="report-tabs"><?php foreach($types as $key=>$label):?><a href="?type=<?=$key?>&from=<?=e($from)?>&to=<?=e($to)?>" class="<?=$type===$key?'active':''?>"><?=e($label)?></a><?php endforeach;?></section><section class="panel"><form class="report-filter"><input type="hidden" name="type" value="<?=e($type)?>"><label>From<input type="date" name="from" value="<?=e($from)?>"></label><label>To<input type="date" name="to" value="<?=e($to)?>"></label><label>Cash / Credit<select name="payment"><option value="">All</option><option value="cash" <?=$payment==='cash'?'selected':''?>>Cash</option><option value="credit" <?=$payment==='credit'?'selected':''?>>Credit</option></select></label><label>Retail / Wholesale<select name="channel"><option value="">All</option><option value="retail" <?=$channel==='retail'?'selected':''?>>Retail</option><option value="wholesale" <?=$channel==='wholesale'?'selected':''?>>Wholesale</option></select></label><button class="btn primary">Apply Filters</button></form></section><section class="kpi-grid report-kpis"><article class="kpi"><span>Quantity / Count</span><strong><?=number_format($totalQty,3)?></strong></article><article class="kpi"><span>Sales / Value</span><strong><?=money($totalSales)?></strong></article><article class="kpi"><span>Saved Product Cost</span><strong><?=money($totalCost)?></strong></article><article class="kpi"><span>Gross Profit</span><strong><?=money($totalProfit)?></strong></article></section><section class="panel table-panel"><div class="panel-head"><div><span class="eyebrow">Full details</span><h3><?=count($rows)?> row(s)</h3></div></div><div class="table-wrap"><table><thead><tr><th>Reference</th><th>Name</th><th class="right">Qty / Count</th><th class="right">Sales / Value</th><th class="right">Saved Cost</th><th class="right">Gross Profit</th><th>Details</th><th></th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="8"><div class="empty-state compact"><b>No records for these filters</b></div></td></tr><?php endif;?><?php foreach($rows as $r):?><tr><td><b><?=e($r['reference'])?></b></td><td><?=e($r['name'])?></td><td class="right"><?=number_format((float)$r['quantity'],3)?></td><td class="right"><?=money($r['sales'])?></td><td class="right"><?=money($r['cost'])?></td><td class="right"><b><?=money($r['profit'])?></b></td><td><?=e($r['detail'])?></td><td><?php if($r['sale_id']):?><a href="sale_view.php?id=<?=$r['sale_id']?>">View</a><?php endif;?></td></tr><?php endforeach;?></tbody><tfoot><tr><th colspan="2">TOTAL</th><th class="right"><?=number_format($totalQty,3)?></th><th class="right"><?=money($totalSales)?></th><th class="right"><?=money($totalCost)?></th><th class="right"><?=money($totalProfit)?></th><th colspan="2"></th></tr></tfoot></table></div></section><style>.report-head{display:flex;justify-content:space-between;align-items:end;margin-bottom:16px}.report-head h2{margin:5px 0}.report-tabs{display:flex;gap:8px;overflow-x:auto;padding-bottom:10px}.report-tabs a{background:#fff;border:1px solid #e3e8e2;padding:10px 13px;border-radius:9px;white-space:nowrap;font-weight:700;font-size:12px}.report-tabs a.active{background:#174e39;color:#fff}.report-filter{display:flex;gap:12px;align-items:end}.report-kpis{margin-top:18px}tfoot th{background:#edf4e9}@media(max-width:800px){.report-head,.report-filter{align-items:stretch;flex-direction:column}}@media print{.sidebar,.topbar,.report-tabs,.report-filter,.report-head .btn{display:none!important}.app{margin:0!important;width:100%!important}.content{padding:0!important}}</style><?php page_end();
